import fixture from '../../fixtures/report-catalog.json'
import { parseDocument, type DashboardDocument } from '../contract'
import { parseCatalogPage, parseDestinations, type ReportCatalogHost, type ReportDestinationHost } from '../reports/picker'
import { parseReportComposition } from '../reports/draft'
import type { CatalogEntry } from '../reports/contract/types'

// Generated by `go run ./cmd/lens-report-example --catalog`: fifty readable
// synthetic reports for a target that already places the first one.
export const catalogEntries = (): CatalogEntry[] => parseCatalogPage(structuredClone(fixture.page)).entries
export const catalogTarget = () => parseReportComposition(structuredClone(fixture.target))
export const catalogPreview = (): DashboardDocument => parseDocument(structuredClone(fixture.preview))
export const catalogDestinations = () => parseDestinations(structuredClone(fixture.destinations))

const never = <T>(signal: AbortSignal) => new Promise<T>((_resolve, reject) => {
  signal.addEventListener('abort', () => reject(new DOMException('Aborted', 'AbortError')))
})

export interface MemoryCatalogOptions {
  entries?: CatalogEntry[]
  /** Searches that fail before the catalog answers. */
  failures?: number
  /** Leave every search pending. */
  pending?: boolean
  /** Previews that fail before one succeeds. */
  previewFailures?: number
}

/** An in-memory host: substring search, owner scope and offset cursors. */
export function memoryCatalog(options: MemoryCatalogOptions = {}): ReportCatalogHost & { searches: number } {
  const entries = options.entries ?? catalogEntries()
  let failures = options.failures ?? 0
  let previewFailures = options.previewFailures ?? 0
  const host = {
    searches: 0,
    search(query, { signal }) {
      host.searches += 1
      if (options.pending) return never(signal)
      if (failures > 0) {
        failures -= 1
        return Promise.reject(new Error('synthetic catalog failure'))
      }
      const needle = (query.search ?? '').toLowerCase()
      const scoped = entries.filter((entry) => (query.scope === 'personal' ? entry.ownership === 'personal'
        : query.scope === 'shared' ? entry.ownership === 'shared' : true))
        .filter((entry) => !needle || entry.title.toLowerCase().includes(needle))
      const offset = Number(query.cursor ?? 0)
      const limit = query.limit ?? 20
      const page = scoped.slice(offset, offset + limit)
      return Promise.resolve({ entries: structuredClone(page), next: offset + limit < scoped.length ? String(offset + limit) : undefined })
    },
    preview(_entry, { signal }) {
      if (previewFailures > 0) {
        previewFailures -= 1
        return Promise.reject(new Error('synthetic preview failure'))
      }
      return signal.aborted ? never(signal) : Promise.resolve(catalogPreview())
    },
  } satisfies ReportCatalogHost & { searches: number }
  return host
}

export function memoryDestinations(options: { failures?: number } = {}): ReportDestinationHost {
  let failures = options.failures ?? 0
  return {
    destinations({ search }) {
      if (failures > 0) {
        failures -= 1
        return Promise.reject(new Error('synthetic destination failure'))
      }
      const needle = search.toLowerCase()
      return Promise.resolve(catalogDestinations().filter((destination) => destination.title.toLowerCase().includes(needle)))
    },
  }
}
